  const walk = async (currentPath, currentDepth, prefix) => {
    if (emitted >= input.maxEntries || currentDepth < 0) {
      return;
    }
    let entries = await readdir9(currentPath, { withFileTypes: true });
    entries = entries.filter((entry) => input.includeHidden || !entry.name.startsWith(".")).sort((left, right) => {
      if (left.isDirectory() && !right.isDirectory()) {
        return -1;
      }
      if (!left.isDirectory() && right.isDirectory()) {
        return 1;
      }
      return left.name.localeCompare(right.name);
    });
    for (const entry of entries) {
      if (emitted >= input.maxEntries) {
        lines.push(`${prefix}…`);
        return;
      }
      emitted += 1;
      lines.push(`${prefix}${entry.isDirectory() ? `${entry.name}/` : entry.name}`);
      if (entry.isDirectory() && currentDepth > 0) {
        await walk(join(currentPath, entry.name), currentDepth - 1, `${prefix}  `);
      }
    }
  };
