var SYSTEM_REMINDER_RE = /<system-reminder>[\s\S]*?<\/system-reminder>/g;
var TURN_META_RE = /<!--\s*turn-meta:.*?-->/g;
var READ_TOOL_LINE_RE = /^[ \t]*\d+→.*$/gm;
function sanitizeStewardOutput(text) {
  if (!text) {
    return text;
  }
  let result = text;
  result = result.replace(SYSTEM_REMINDER_RE, "");
  result = result.replace(TURN_META_RE, "");
  result = result.replace(READ_TOOL_LINE_RE, "");
  result = result.replace(/\n{3,}/g, `

`);
  return result;
}

